from collections import deque


class RateWindow:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = deque()

    def allow(self, t):
        # Prune expired events: an event e counts only while e > t - window
        while self.events and self.events[0] <= t - self.window:
            self.events.popleft()

        # Check if we can allow this event
        if len(self.events) < self.limit:
            self.events.append(t)
            return True
        else:
            # Rejected call must not consume quota (do not append)
            return False

    def retry_after(self, t):
        if not self.events:
            return 0

        # Prune expired events first to get accurate count
        while self.events and self.events[0] <= t - self.window:
            self.events.popleft()

        if not self.events:
            return 0

        if len(self.events) < self.limit:
            return 0

        # We're at capacity; need to wait until the oldest event expires
        # The oldest event at self.events[0] expires when t > self.events[0] + self.window
        # So we need to wait until time = self.events[0] + self.window + epsilon
        # But since we use strict inequality, at exactly self.events[0] + self.window,
        # the event no longer counts. So retry time is max(0, self.events[0] + self.window - t)
        wait_time = self.events[0] + self.window - t
        return max(0.0, wait_time)
