import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]"
    tokens = re.findall(token_pattern, s)

    # Reconstruct and validate: remove spaces from input, ensure all non-space chars are tokenized
    cleaned = s.replace(" ", "")
    reconstructed = "".join(tokens)
    if reconstructed != cleaned:
        raise ValueError("Invalid characters in expression")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect(tok):
        t = take()
        if t != tok:
            raise ValueError(f"Expected {tok}, got {t}")
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/" and r == 0:
                raise ZeroDivisionError("division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        v = atom()
        if peek() == "^":
            take()
            # Right-associative: recursively parse the rest as a unary-powered expression
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            take()
            return v
        if t is None:
            raise ValueError("Missing operand")
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError("Missing operand")
        take()
        return float(t)

    result = expr()
    if peek() is not None:
        raise ValueError("Unexpected token after expression")
    return result
