```python
def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Rules:
    - Variables must start with `prefix` (default "APP_").
    - The part after the prefix is lowercased and split by double underscores "__" to form the path.
    - A single underscore is part of the key name, not a separator.
    - The raw string is converted to the type of the default value.
    - Bool: accepts 1/true/yes/on (True) or 0/false/no/off (False), case-insensitive; else ValueError.
    - int/float: parsed numerically; else ValueError.
    - Other types: kept as string (no conversion attempted).
    - Variables without the prefix or paths not in defaults are ignored.
    - The defaults object is never modified.
    """
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    def convert_value(value, target_type):
        if target_type is bool:
            lower_val = value.lower()
            if lower_val in ("1", "true", "yes", "on"):
                return True
            elif lower_val in ("0", "false", "no", "off"):
                return False
            else:
                raise ValueError(f"Invalid boolean value: {value}")
        elif target_type is int:
            return int(value)
        elif target_type is float:
            return float(value)
        else:
            # For any other type, keep as string (do not attempt conversion)
            return value

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        # Extract path: remove prefix, lowercase, split by double underscore
        path_str = k[len(prefix):].lower()
        path = path_str.split("__")

        # Traverse the config tree to find the target node
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if isinstance(node, dict) and p in node:
                node = node[p]
            else:
                valid_path = False
                break

        if not valid_path:
            continue

        # Check if the final key exists
        final_key = path[-1]
        if not isinstance(node, dict) or final_key not in node:
            continue

        # Get the default value to determine target type
        default_val = node[final_key]
        target_type = type(default_val)

        try:
            converted = convert_value(raw, target_type)
            node[final_key] = converted
        except (ValueError, TypeError):
            # Ignore variables that cannot be converted to the target type
            continue

    return cfg
