class Autocomplete:
    def __init__(self):
        self.root = {}
        self.size = 0

    def add(self, word, weight=1):
        node = self.root
        lower_word = word.lower()
        for ch in lower_word:
            node = node.setdefault(ch, {})
        if "$" not in node:
            self.size += 1
            node["$"] = 0
        node["$"] += weight

    def remove(self, word):
        node = self.root
        lower_word = word.lower()
        for ch in lower_word:
            if ch not in node:
                return False
            node = node[ch]
        if "$" not in node:
            return False
        del node["$"]
        self.size -= 1
        return True

    def suggest(self, prefix, k=5):
        if k <= 0:
            return []

        node = self.root
        lower_prefix = prefix.lower()
        for ch in lower_prefix:
            if ch not in node:
                return []
            node = node[ch]

        found = []

        def walk(n, acc):
            for key, child in n.items():
                if key == "$":
                    found.append((child, acc))
                else:
                    walk(child, acc + key)

        walk(node, lower_prefix)
        # Sort by weight descending, then by word ascending (alphabetical)
        found.sort(key=lambda x: (-x[0], x[1]))
        return [w for _, w in found[:k]]

    def __len__(self):
        return self.size
