import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    # Pattern: float/int with optional decimal, or one of the operator chars.
    token_pattern = re.compile(r"\d+\.?\d*|\.\d+|[-+*/^()]")

    # First, validate that the string contains only allowed characters and spaces
    allowed_pattern = re.compile(r"^[\d\s\.\+\-\*\/\^\(\)]*$")
    if not allowed_pattern.match(s):
        raise ValueError("Invalid characters in expression")

    toks = token_pattern.findall(s)

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            v = v * r if op == "*" else v / r
        return v

    def power():
        # Right-associative exponentiation with unary handling in exponent
        v = atom()
        if peek() == "^":
            take()
            # Exponent may carry a sign; parse unary +/- before the next atom
            exp_val = signed_atom()
            v = v ** exp_val
            # Continue chaining for right-associativity: a^b^c = a^(b^c)
            if peek() == "^":
                # Recursively handle the rest as a power expression
                remaining = power()
                v = v ** remaining
        return v

    def signed_atom():
        # Handle unary + or - before an atom (for exponent context)
        t = peek()
        if t == "+":
            take()
            return signed_atom()
        if t == "-":
            take()
            return -signed_atom()
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")

        if t == "-":
            take()
            return -atom()
        if t == "+":
            take()
            return atom()
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError(f"Unexpected operator or parenthesis: {t}")

        # Must be a number
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()

    if pos != len(toks):
        raise ValueError("Unexpected tokens after expression")

    return result
