    if not s or not s.strip():
        raise ValueError("Empty input")

    # Check for invalid characters before tokenizing
    # Allowed: digits, dot, + - * / ^ ( ) and whitespace
    if re.search(r"[^\d.\+\-\*\/\^\(\)\s]", s):
        raise ValueError("Unknown characters in input")

    # Tokenize: numbers (int, float, .float) and operators/parens
    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", s)

    if not toks:
        raise ValueError("No tokens found")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            # Ensure there is a right operand
            if peek() is None or peek() in (")",):
                raise ValueError("Missing operand after operator")
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            # Handle unary signs after * or /
            if peek() in ("+", "-"):
                # This is handled by power() -> atom() which accepts unary +/-
                pass
            if peek() is None or peek() in (")",):
                raise ValueError("Missing operand after operator")
            r = power()
            if op == "/" and r == 0:
                raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def power():
        # Right-associative exponentiation with unary support in exponent
        v = atom()
        while peek() == "^":
            take()  # consume '^'
            # Exponent can have a sign, e.g., 2^-1
            # Our atom() already handles leading unary +/-
            if peek() is None:
                raise ValueError("Missing exponent")
            right = atom()
            v = v ** right
        return v

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")

        if t == "-":
            take()
            # Unary minus
            return -atom()
        if t == "+":
            take()
            # Unary plus
            return atom()
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            take()  # consume ')'
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Unexpected operator or parenthesis")

        # Must be a number
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()

    # Ensure all tokens are consumed
    if peek() is not None:
        raise ValueError("Unexpected tokens at end of expression")

    return result
