def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index equal to list length appends.
    - Index larger than list length pads with None up to that index.
    - Type mismatches (key on list/scalar, index on dict/scalar) raise TypeError.
    - Empty or malformed paths raise ValueError.
    - First step must be a key, and obj must be a dict.
    """

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path:
        raise ValueError("Path cannot be empty")

    # Validate path format before processing
    # Check for invalid patterns: "..", starting with ".", ending with ".", 
    # negative indices, non-numeric indices, unclosed brackets
    if path.startswith(".") or path.endswith("."):
        raise ValueError("Malformed path: cannot start or end with a dot")

    if ".." in path:
        raise ValueError("Malformed path: consecutive dots not allowed")

    # Parse path into steps
    # We need to carefully split by dots, but respect brackets
    # Strategy: replace "[index]" with a special delimiter, split, then restore
    # Actually, let's parse manually to handle all edge cases

    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                steps.append(('key', current))
                current = ""
            elif not steps:  # dot at start already checked, but double check
                raise ValueError("Malformed path")
            # if current is empty and we have steps, it means ".." which is checked above
        elif ch == '[':
            if current:
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError("Malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("Malformed path: empty index")
            if index_str.startswith('-'):
                raise ValueError("Malformed path: negative index not allowed")
            if not index_str.isdigit():
                raise ValueError("Malformed path: non-numeric index")
            steps.append(('index', int(index_str)))
            i = j  # move to ']'
        else:
            current += ch
        i += 1

    if current:
        steps.append(('key', current))

    if not steps:
        raise ValueError("Path cannot be empty")

    if steps[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy function for dict/list structures
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    # Create a deep copy to avoid mutating the original
    result = deep_copy(obj)

    node = result

    # Navigate to the parent of the target location
    for step_type, step_value in steps[:-1]:
        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key step on non-dict")
            if step_value not in node:
                # Determine next step to decide what to create
                next_type, _ = steps[steps.index((step_type, step_value)) + 1]
                if next_type == 'key':
                    node[step_value] = {}
                else:
                    node[step_value] = []
            node = node[step_value]
        else:  # index
            if not isinstance(node, list):
                raise TypeError("Cannot use index step on non-list")
            idx = step_value
            if idx > len(node):
                # Pad with None
                node.extend([None] * (idx - len(node)))
            if idx == len(node):
                # Append new container based on next step
                next_type, _ = steps[steps.index((step_type, step_value)) + 1]
                if next_type == 'key':
                    node.append({})
                else:
                    node.append([])
            elif node[idx] is None:
                # Create container if None
                next_type, _ = steps[steps.index((step_type, step_value)) + 1]
                if next_type == 'key':
                    node[idx] = {}
                else:
                    node[idx] = []
            node = node[idx]

    # Set the final value
    last_type, last_value = steps[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_value] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")
        idx = last_value
        if idx > len(node):
            node.extend([None] * (idx - len(node)))
        if idx == len(node):
            node.append(value)
        else:
            node[idx] = value

    return result
