                raise ValueError(f"Malformed path: {path}")
            steps.append(("index", int(index_str)))
            i = j  # Will be incremented at end of loop
        else:
            current += ch
        i += 1

    if current:
        steps.append(("key", current))

    if not steps:
        raise ValueError("Path must have at least one step")

    if steps[0][0] != "key":
        raise ValueError("First step must be a key")

    # Deep copy the object to ensure immutability of original
    result = copy.deepcopy(obj)

