        elif isinstance(node, list):
            raise TypeError(f"Cannot use key '{last_val}' on a list")
        else:
            raise TypeError(f"Cannot use key '{last_val}' on a scalar")
    else:  # index
        idx = last_val
        if isinstance(node, list):
            if idx < 0:
