    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created.
    - Missing containers: dict if next step is key, list if next step is index.
    - Index == len(list) appends; index > len(list) pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty, malformed, or starts with index.
    - First step must be a key; obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")
    if not path:
        raise ValueError("Path cannot be empty")

    # Validate path format before parsing
    if path.startswith(".") or path.startswith("["):
        raise ValueError("Path must start with a key")
    if ".." in path:
        raise ValueError("Path contains empty key")
    if path.endswith("."):
        raise ValueError("Path ends with empty key")

    # Parse path into steps: each step is ('key', str) or ('index', int)
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == ".":
            if current == "":
                raise ValueError("Empty key in path")
            steps.append(("key", current))
            current = ""
        elif ch == "[":
            if current != "":
                steps.append(("key", current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != "]":
                j += 1
            if j == len(path):
                raise ValueError("Unclosed bracket in path")
            idx_str = path[i+1:j]
            if idx_str == "":
                raise ValueError("Empty index in path")
            if idx_str.startswith("-"):
                raise ValueError("Negative indices not supported")
            if not idx_str.isdigit():
                raise ValueError(f"Invalid index: {idx_str}")
            steps.append(("index", int(idx_str)))
            i = j  # will be incremented at end of loop
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(("key", current))

    if not steps:
        raise ValueError("Path resulted in no steps")

    # Deep copy helper
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    # Start with a deep copy to ensure immutability of original
    result = deep_copy(obj)
    node = result

    # Navigate/create structure up to the second-to-last step
    for idx in range(len(steps) - 1):
        step_type, step_val = steps[idx]
        next_type, next_val = steps[idx + 1]

        if step_type == "key":
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at key '{step_val}', found {type(node).__name__}")
            if step_val not in node:
                # Create next container based on next step
                if next_type == "key":
                    node[step_val] = {}
                else:
                    node[step_val] = []
            node = node[step_val]
        else:  # step_type == "index"
            if not isinstance(node, list):
                raise TypeError(f"Expected list at index {step_val}, found {type(node).__name__}")
            if step_val < 0 or step_val > len(node):
                raise IndexError(f"Index {step_val} out of range for list of length {len(node)}")
            if step_val == len(node):
                # Append new container based on next step
                if next_type == "key":
                    node.append({})
                else:
                    node.append([])
            elif node[step_val] is None:
                # Replace None with appropriate container
                if next_type == "key":
                    node[step_val] = {}
                else:
                    node[step_val] = []
            elif node[step_val] is not None:
                # Check type compatibility
                existing = node[step_val]
                if next_type == "key" and not isinstance(existing, dict):
                    raise TypeError(f"Expected dict at index {step_val}, found {type(existing).__name__}")
                if next_type == "index" and not isinstance(existing, list):
                    raise TypeError(f"Expected list at index {step_val}, found {type(existing).__name__}")
            node = node[step_val]

    # Set the final value
    last_type, last_val = steps[-1]
    if last_type == "key":
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict to set key '{last_val}', found {type(node).__name__}")
        node[last_val] = value
    else:  # last_type == "index"
        if not isinstance(node, list):
            raise TypeError(f"Expected list to set index {last_val}, found {type(node).__name__}")
        if last_val < 0:
            raise IndexError("Negative indices not supported")
        if last_val > len(node):
            # Pad with None up to last_val - 1, then set value
            while len(node) < last_val:
                node.append(None)
            node.append(value)
        elif last_val == len(node):
            node.append(value)
        else:
            node[last_val] = value

    return result
