def running_balance(opening, transactions):
    """Apply transactions in order. Each is a dict {"type": "credit" or "debit", "amount": positive int cents}. Returns (closing_balance, balances_after_each_transaction). Balance may go negative on a debit. Raises ValueError for an unknown type or an amount that is not a positive int, before changing anything. Does not modify the input transactions."""
    # Validate all transactions first; do not mutate anything if any are invalid.
    valid_types = {"credit", "debit"}
    for t in transactions:
        t_type = t.get("type")
        t_amount = t.get("amount")
        if t_type not in valid_types:
            raise ValueError(f"Unknown transaction type: {t_type!r}")
        if not isinstance(t_amount, int) or t_amount <= 0:
            raise ValueError(f"Invalid amount: {t_amount!r}; must be a positive int")

    balances = []
    bal = opening
    for t in transactions:
        if t["type"] == "credit":
            bal += t["amount"]
        else:  # debit
            bal -= t["amount"]
        balances.append(bal)
    return bal, balances
