    current_len = 0

    for word in words:
        # Length if we add this word (plus space if not first)
        word_len = len(word)
        if result_words:
            needed = current_len + 1 + word_len  # +1 for space
        else:
            needed = word_len

        if needed <= max_content_len:
            result_words.append(word)
            current_len = needed
        else:
            break

    if result_words:
        return " ".join(result_words) + suffix
    else:
        # Not even the first word fits; hard-cut
