def anagram_groups(words):
    """Group words that are anagrams of each other. Comparison is case-insensitive and uses letters only (spaces, digits and punctuation are ignored); words with no letters are ignored. Identical strings count once. Return only groups with 2 or more distinct words: each group sorted alphabetically ignoring case (original spelling kept), the groups ordered by their first member (ignoring case)."""
    groups = {}
    seen_normalized = {}  # Track normalized forms to handle identical strings (case-insensitive)

    for w in words:
        # Extract letters only and convert to lowercase for normalization
        letters = [c.lower() for c in w if c.isalpha()]

        # Ignore words with no letters
        if not letters:
            continue

        normalized_word = "".join(letters)
        sorted_key = "".join(sorted(letters))

        # Check if we've already seen this exact normalized word (case-insensitive duplicate)
        if sorted_key in seen_normalized:
            if normalized_word in seen_normalized[sorted_key]:
                continue  # Skip duplicate words (case-insensitive)
            seen_normalized[sorted_key].add(normalized_word)
        else:
            seen_normalized[sorted_key] = {normalized_word}

        if sorted_key not in groups:
            groups[sorted_key] = []
        groups[sorted_key].append(w)

    result = []
    for g in groups.values():
        if len(g) > 1:
            # Sort group alphabetically ignoring case, keeping original spelling
            sorted_group = sorted(g, key=lambda x: x.lower())
            result.append(sorted_group)

    # Sort groups by their first member (ignoring case)
    result.sort(key=lambda x: x[0].lower())

    return result
