import re


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""

    # Validate characters: allow digits, operators, parentheses, whitespace
    if re.search(r"[^\d+\-*/()\s]", expr):
        raise ValueError("Invalid character in expression")

    # Tokenize: numbers, operators, parentheses
    tokens = re.findall(r"\d+|[-+*/()]", expr)

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            eat()  # consume ')'
            return v
        if t == "-":
            return -atom()
        if t in "+*/)":
            raise ValueError("Dangling operator")
        if not t.isdigit():
            raise ValueError("Invalid token")
        return int(t)

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            right = atom()
            if op == "*":
                v = v * right
            else:
                v = v / right
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            right = mul()
            if op == "+":
                v = v + right
            else:
                v = v - right
        return v

    result = add()

    if pos != len(tokens):
        raise ValueError("Extra tokens after expression")

    return result
