import re


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""

    # Pre-validation: check for empty/whitespace-only input
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Tokenize: numbers, operators, parentheses, and capture spaces to detect invalid chars
    # We need to ensure ONLY valid characters are present
    raw_tokens = re.findall(r"\d+|[-+*/()]|\s+|.", expr)

    # Filter out whitespace and validate no invalid characters exist
    tokens = []
    for t in raw_tokens:
        if t.isspace():
            continue
        if re.match(r"\d+|[-+*/()]", t) is None:
            raise ValueError(f"Invalid character: {t}")
        tokens.append(t)

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")

        if t == "(":
            eat()  # consume '('
            v = add()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            eat()  # consume ')'
            return v

        if t == "-":
            eat()  # consume '-'
            return -atom()

        if t == "+":
            # Unary plus is not explicitly mentioned but typically allowed; 
            # however, spec says "dangling operator" is error. 
            # Let's treat unary + similar to unary - for consistency, or reject?
            # The spec says "unary minus", not unary plus. Let's be strict.
            # But wait, "1+2" is fine. "+1" as start? Spec doesn't say unary plus is allowed.
            # Let's assume only unary minus as per spec. If we see a bare '+', it's a dangling operator.
            raise ValueError("Dangling operator: +")

        if t in ("*", "/", ")"):
            raise ValueError(f"Dangling operator: {t}")

        # Must be a number
        if not re.match(r"\d+", t):
            raise ValueError(f"Unexpected token: {t}")

        eat()  # consume number
        return int(t)

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            right = atom()
            if op == "*":
                v = v * right
            else:
                v = v / right
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            right = mul()  # FIXED: was add(), causing right-associativity. Now mul() for left-associativity.
            if op == "+":
                v = v + right
            else:
                v = v - right
        return v

    result = add()

    # Ensure all tokens were consumed
    if pos < len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]}")

    return result
