import json


def _normalize(obj):
    """
    Recursively normalize data structures to ensure stable serialization.
    - Lists are converted to tuples (so [1, 2] != (1, 2) after type tagging).
    - Dicts are sorted by key to ensure order independence.
    - Types are explicitly preserved to distinguish between 1, 1.0, True, etc.
    """
    if obj is None:
        return ("None", None)
    if isinstance(obj, bool):
        # Must check bool before int because bool is a subclass of int
        return ("bool", obj)
    if isinstance(obj, int):
        return ("int", obj)
    if isinstance(obj, float):
        return ("float", obj)
    if isinstance(obj, str):
        return ("str", obj)
    if isinstance(obj, list):
        return ("list", tuple(_normalize(item) for item in obj))
    if isinstance(obj, tuple):
        return ("tuple", tuple(_normalize(item) for item in obj))
    if isinstance(obj, dict):
        # Ensure all keys are strings as per docstring requirements
        for k in obj.keys():
            if not isinstance(k, str):
                raise TypeError("Dict keys must be strings")
        # Sort items by key to ensure deterministic order
        sorted_items = sorted(obj.items(), key=lambda x: x[0])
        return ("dict", tuple((k, _normalize(v)) for k, v in sorted_items))

    raise TypeError(f"Unsupported type for cache_key: {type(obj)}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""

    # Normalize arguments to handle type distinction and structural ordering
    norm_args = tuple(_normalize(arg) for arg in args)

    # Normalize kwargs and sort by key to ensure keyword order independence
    sorted_kwargs_keys = sorted(kwargs.keys())
    norm_kwargs = tuple((k, _normalize(kwargs[k])) for k in sorted_kwargs_keys)

    # Construct a structure that separates args and kwargs clearly
    # Using a specific format: ("args", ...), ("kwargs", ...)
    payload = [
        ("args", norm_args),
        ("kwargs", norm_kwargs)
    ]

    return json.dumps(payload, sort_keys=False)
