def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    if not s:
        return default  # bare sign

    # Split by commas and validate grouping
    parts = s.split(',')

    # If there are commas, validate strict thousands grouping
    if len(parts) > 1:
        # First part (leftmost) can be 1-3 digits
        if not (1 <= len(parts[0]) <= 3):
            return default
        # All subsequent parts must be exactly 3 digits
        for part in parts[1:]:
            if len(part) != 3:
                return default
        # Rejoin without commas for digit validation
        digit_str = ''.join(parts)
    else:
        digit_str = parts[0]

    # Validate that all characters are ASCII digits
    if not digit_str.isdigit():
        return default

    # Ensure no non-ASCII digits (isdigit() allows some Unicode digits)
    if not all(c in '0123456789' for c in digit_str):
        return default

    return sign * int(digit_str)
