def load_config(defaults, env, prefix="APP_"):
    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        else:
            return obj

    def _convert_value(value, target_type):
        if target_type is bool:
            if isinstance(value, str):
                val_lower = value.lower()
                if val_lower in ("1", "true", "yes", "on"):
                    return True
                elif val_lower in ("0", "false", "no", "off"):
                    return False
                else:
                    raise ValueError(f"Invalid boolean value: {value}")
            return bool(value)
        elif target_type is int:
            return int(value)
        elif target_type is float:
            return float(value)
        else:
            # For str or any other type, just return the string as is
            # unless it's already the target type (though env is usually strings)
            return str(value)

    def _set_nested_value(node, path, value, target_type):
        current = node
        # Navigate to the parent of the target key
        for i, key in enumerate(path[:-1]):
            if key not in current:
                # Path does not exist in defaults, ignore this env var
                return
            if not isinstance(current[key], dict):
                # Intermediate path is not a dict, cannot nest further, ignore
                return
            current = current[key]

        last_key = path[-1]
        if last_key not in current:
            # Final key does not exist in defaults, ignore
            return

        current[last_key] = _convert_value(value, target_type)

    # Create a deep copy to ensure defaults are not modified
    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix
        suffix = k[len(prefix):]

        # Split by double underscore for nesting, but keep single underscores in keys
        # The spec says: "a double underscore separates nesting levels"
        # and "a single underscore is part of the key name".
        # Also "PATH is lower-cased".

        # We need to split by '__' specifically.
        parts = suffix.split("__")
        path = [p.lower() for p in parts]

        # Determine the target type from the default value
        node = cfg
        try:
            # Traverse to find the default value's type
            current = node
            valid_path = True
            for p in path[:-1]:
                if p not in current or not isinstance(current[p], dict):
                    valid_path = False
                    break
                current = current[p]

            if not valid_path:
                continue

            last_key = path[-1]
            if last_key not in current:
                continue

            default_val = current[last_key]
            target_type = type(default_val)

            _set_nested_value(cfg, path, raw, target_type)

        except (ValueError, TypeError):
            # If conversion fails, we should probably raise or skip?
            # The spec says "anything else raises ValueError" for bool.
            # For int/float, standard parsing errors apply.
            # Since this is a loader, propagating the ValueError seems correct
            # if the user provided a bad value for a known typed field.
            raise

    return cfg
