def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]"
    toks = re.findall(token_pattern, s)

    # Validate that the entire string is covered by tokens (no garbage)
    reconstructed = "".join(toks)
    if reconstructed != s.replace(" ", ""):
        raise ValueError("Invalid expression: contains unknown characters")

    if not toks:
        raise ValueError("Invalid expression: empty input")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/" and r == 0:
                raise ZeroDivisionError("division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        t = peek()
        if t in ("+", "-"):
            take()
            sign = 1 if t == "+" else -1
            return sign * unary()
        return power()

    def power():
        v = atom()
        while peek() == "^":
            take()
            # Right-associative: exponent is a unary expression (allows -2^2 = -4)
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Invalid expression: unbalanced parentheses")
            take()
            return v
        if t is None:
            raise ValueError("Invalid expression: missing operand")
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Invalid expression: missing operand")
        take()
        return float(t)

    result = expr()

    # Ensure all tokens were consumed (no trailing garbage like "2 3")
    if pos < len(toks):
