import re


def evaluate(s):
    # Validate input: must not be empty or only whitespace
    if not s or not s.strip():
        raise ValueError("Empty expression")

    # Check for invalid characters before tokenizing
    # Allowed: digits, dot, + - * / ^ ( ) and whitespace
    if re.search(r"[^\d.\+\-\*/^\(\)\s]", s):
        raise ValueError("Invalid character in expression")

    # Tokenize: numbers (int, float, .float) and operators/parens
    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", s)

    if not toks:
        raise ValueError("No tokens found")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        if pos >= len(toks):
            raise ValueError("Unexpected end of expression")
        t = toks[pos]
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            v = v * r if op == "*" else v / r
        return v

    def power():
        # Right-associative exponentiation with unary support in exponent
        v = unary()
        if peek() == "^":
            take()
            # The exponent itself can have a sign, so we call unary() again
            # but we need to handle right associativity: a^b^c = a^(b^c)
            # So we recursively parse the rest of the power chain
            exp = unary()
            # Check if there's another ^ immediately after the exponent
            while peek() == "^":
                take()
                next_exp = unary()
                exp = exp ** next_exp
            v = v ** exp
        return v

    def unary():
        t = peek()
        if t in ("+", "-"):
            take()
            val = unary()
            return -val if t == "-" else val
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            take()  # consume '('
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            take()  # consume ')'
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError("Missing operand")
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError("Invalid number")

    result = expr()

    # Ensure all tokens were consumed
    if pos < len(toks):
        raise ValueError("Unexpected tokens at end of expression")

    return result
