def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Rules:
    - Variables must start with `prefix` (default "APP_").
    - The part after the prefix is lowercased and split by double underscores "__" to form the path.
    - A single underscore "_" is treated as part of the key name, not a separator.
    - The raw string value is converted to the type of the corresponding default value.
    - Bool conversion accepts: 1/true/yes/on (True) and 0/false/no/off (False), case-insensitive.
      Any other value for bool raises ValueError.
    - Int and Float are parsed normally.
    - Other types remain as strings (or if the default is a string, the raw value is used).
    - Variables without the prefix or paths not existing in defaults are ignored.
    - The defaults object is never modified.
    """

    def convert_value(target_type, raw_value):
        if target_type is bool:
            v = raw_value.lower()
            if v in ("1", "true", "yes", "on"):
                return True
            elif v in ("0", "false", "no", "off"):
                return False
            else:
                raise ValueError(f"Invalid boolean value: {raw_value}")
        elif target_type is int:
            return int(raw_value)
        elif target_type is float:
            return float(raw_value)
        else:
            # For str or any other type, return the raw string as is
            return raw_value

    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    # Create a deep copy to ensure defaults is not modified and nested dicts are independent
    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix
        key_part = k[len(prefix):]

        # Split by double underscore for nesting levels
        path = key_part.lower().split("__")

        # Traverse the config to find the target node
        node = cfg
        valid_path = True

        try:
            for p in path[:-1]:
                if p not in node:
                    valid_path = False
                    break
                node = node[p]

            if not valid_path:
                continue

            final_key = path[-1]
            if final_key not in node:
                continue

            # Get the type of the default value
            target_type = type(node[final_key])

            # Convert and assign
            node[final_key] = convert_value(target_type, raw)

        except (KeyError, TypeError, ValueError):
            # Ignore invalid paths or conversion errors as per "ignored" rule for non-existent paths
            # However, bool ValueError should probably propagate if the path exists but value is bad?
            # The ticket says "anything else raises ValueError" for bool.
            # But it also says "paths that do not exist ... are ignored".
            # If the path exists but conversion fails, we let the ValueError bubble up for bool,
            # or ignore for missing keys (handled above).
            # Re-reading: "anything else raises ValueError" implies strictness for bool.
            # But "unknown variable crashes startup" is a bug. Unknown variable = key not in defaults.
            # We already handle missing keys by `continue`.
            # So if we are here, the path exists. If conversion fails, it should raise.
            raise

    return cfg
