def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing containers for index steps are created as lists.
    - Index equal to list length appends; larger index pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty or malformed.
    - First step must be a key; obj must be a dict.
    """

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or path.startswith(".") or path.endswith("."):
        raise ValueError("Path is empty or malformed")

    # Validate and parse path
    parts = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("Malformed path: empty segment")
            parts.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                parts.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '.' or path[j] == '[':
                    raise ValueError("Malformed path: invalid characters in index")
                j += 1
            if j >= len(path):
                raise ValueError("Malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if not index_str.isdigit() and not (index_str.startswith('-') and index_str[1:].isdigit()):
                raise ValueError("Malformed path: non-numeric index")
            if index_str.startswith('-'):
                raise ValueError("Malformed path: negative index not allowed")
            parts.append(('index', int(index_str)))
            i = j
        else:
            current += ch
        i += 1

    if current != "":
        parts.append(('key', current))

    if not parts:
        raise ValueError("Path is empty")

    if parts[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy function to ensure no shared mutable state
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    result = deep_copy(obj)
    node = result

    # Navigate through all parts except the last one, creating missing containers
    for step_type, step_value in parts[:-1]:
        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key step on non-dict")
            if step_value not in node:
                # Determine what the next step needs
                next_type, _ = parts[parts.index((step_type, step_value)) + 1]
                if next_type == 'key':
                    node[step_value] = {}
                else:
                    node[step_value] = []
            node = node[step_value]
        else:  # index
            if not isinstance(node, list):
                raise TypeError("Cannot use index step on non-list")
            idx = step_value
            if idx > len(node):
                # Pad with None up to the index
                node.extend([None] * (idx - len(node)))
            elif idx == len(node):
                node.append(None)
            # If idx < len(node), we just access existing element
            if node[idx] is None:
                # Determine what the next step needs
                next_type, _ = parts[parts.index((step_type, step_value)) + 1]
                if next_type == 'key':
                    node[idx] = {}
                else:
                    node[idx] = []
            node = node[idx]

    # Set the final value
    last_type, last_value = parts[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_value] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")
        idx = last_value
        if idx > len(node):
            node.extend([None] * (idx - len(node)))
        elif idx == len(node):
            node.append(value)
            return result
        node[idx] = value

    return result
