def set_path(obj, path, value):
    """
    Returns a new structure with the location named by `path` set to `value`.
    The original `obj` and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("Root object must be a dict")
    if not path:
        raise ValueError("Path cannot be empty")

    # Deep copy helper to ensure full independence of mutable structures
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        if isinstance(item, list):
            return [deep_copy(v) for v in item]
        return item

    # Parse path into steps: list of ('key', str) or ('index', int)
    steps = []
    # Split by dots, but keep bracket parts intact
    # Strategy: replace '[', ']' temporarily to avoid split issues, or manual parse
    # Manual parse is safer for malformed detection
    i = 0
    current = ""
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError(f"Malformed path: empty segment at {i}")
            steps.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError(f"Malformed path: unclosed bracket at {i}")
            inner = path[i+1:j]
            if inner == "":
                raise ValueError(f"Malformed path: empty index at {i}")
            if inner.startswith('-') or (not inner.isdigit()):
                raise ValueError(f"Malformed path: invalid index '{inner}' at {i}")
            steps.append(('index', int(inner)))
            i = j  # will be incremented at end of loop
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(('key', current))

    if not steps:
        raise ValueError("Path cannot be empty")

    # First step must be a key
    if steps[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Work on a deep copy
    result = deep_copy(obj)
    node = result

    # Navigate/create up to the second-to-last step
    for idx in range(len(steps) - 1):
        step_type, step_val = steps[idx]
        next_type, next_val = steps[idx + 1]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key on non-dict")
            if step_val not in node:
                # Create container based on next step
                if next_type == 'index':
                    node[step_val] = []
                else:
                    node[step_val] = {}
            node = node[step_val]
        else:  # index
            if not isinstance(node, list):
                raise TypeError("Cannot use index on non-list")
            if step_val < 0 or step_val > len(node):
                raise IndexError(f"Index {step_val} out of range")
            if step_val == len(node):
                # Append new container based on next step
                if next_type == 'index':
                    node.append([])
                else:
                    node.append({})
            node = node[step_val]

    # Set the final value
    last_type, last_val = steps[-1]
    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot use key on non-dict")
        node[last_val] = value
    else:  # index
        if not isinstance(node, list):
            raise TypeError("Cannot use index on non-list")
        if last_val < 0:
            raise IndexError(f"Index {last_val} out of range")
        # Pad with None if needed
        while len(node) < last_val:
            node.append(None)
        if last_val == len(node):
            node.append(value)
        else:
            node[last_val] = value

    return result
