import re


def glob_match(pattern, path):
    """
    Matches a glob pattern against a path.

    Rules:
    - '*': Matches any sequence of characters except '/'.
    - '?': Matches exactly one character except '/'.
    - '**': Matches any sequence of characters including '/'.
    - '**/': Matches zero or more whole directories (equivalent to matching anything ending in '/' or empty).
    - '[...]': Character class. '[!...]' or '[^...]' negates. '-' denotes range. Never matches '/'.
    - '\\': Escapes the next character.
    - Case-sensitive.
    - Leading dot is not special.
    """

    # Tokenize the pattern
    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]

        if c == '\\':
            if i + 1 < n:
                tokens.append(('LITERAL', pattern[i+1]))
                i += 2
            else:
                tokens.append(('LITERAL', '\\'))
                i += 1

        elif c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                # Check for **
                if i + 2 < n and pattern[i+2] == '/':
                    # **/
                    tokens.append(('DOUBLE_STAR_SLASH',))
                    i += 3
                else:
                    # ** (not followed by /, or at end)
                    tokens.append(('DOUBLE_STAR',))
                    i += 2
            else:
                # Single *
                tokens.append(('SINGLE_STAR',))
                i += 1

        elif c == '?':
            tokens.append(('QUESTION',))
            i += 1

        elif c == '[':
            # Parse character class
            j = i + 1
            if j >= n:
                tokens.append(('LITERAL', '['))
                i += 1
                continue

            negated = False
            if j < n and pattern[j] in '!^':
                negated = True
                j += 1

            if j >= n:
                tokens.append(('LITERAL', '['))
                i += 1
                continue

            # Handle ] as first char in class
            if j < n and pattern[j] == ']':
                j += 1

            chars = set()
            ranges = []

            while j < n and pattern[j] != ']':
                start = pattern[j]
                j += 1

                if j + 1 < n and pattern[j] == '-' and pattern[j+1] != ']':
                    end = pattern[j+1]
                    j += 2
                    # Add range
                    for code in range(ord(start), ord(end) + 1):
                        char = chr(code)
                        if char == '/':
                            continue # Classes never match /
                        if negated:
                            chars.add(char)
                        else:
                            chars.add(char)
                    # We handle negation logic at match time by storing structure
                    # Actually, simpler to store the raw range and evaluate at match time
                    ranges.append((start, end))
                else:
                    if start == '/':
                        pass # Never match /
                    elif negated:
                        chars.add(start)
                    else:
                        chars.add(start)

            if j >= n:
                # Unclosed bracket, treat as literal
                tokens.append(('LITERAL', '['))
                i += 1
            else:
                tokens.append(('CHAR_CLASS', negated, chars, ranges))
                i = j + 1

        else:
            tokens.append(('LITERAL', c))
            i += 1

    # Now match tokens against path
    # We use recursion with memoization or iterative DP
    # State: (token_index, path_index)

    memo = {}

    def match(ti, pi):
        # ti: current token index
        # pi: current path index

        if (ti, pi) in memo:
            return memo[(ti, pi)]

        # Base case: no more tokens
        if ti == len(tokens):
            res = (pi == len(path))
            memo[(ti, pi)] = res
            return res

        token = tokens[ti]
        kind = token[0]

        if kind == 'LITERAL':
            val = token[1]
            if pi < len(path) and path[pi] == val:
                res = match(ti + 1, pi + 1)
            else:
                res = False

        elif kind == 'QUESTION':
            if pi < len(path) and path[pi] != '/':
                res = match(ti + 1, pi + 1)
            else:
                res = False

        elif kind == 'SINGLE_STAR':
            # Match 0 or more non-slash characters
            # Try matching 0, then 1, etc.
            # Optimization: iterate until slash or end
            res = False
            # Option 1: Match empty
            if match(ti + 1, pi):
                res = True
            else:
                # Option 2: Match characters
                k = pi
                while k < len(path) and path[k] != '/':
                    k += 1
                    if match(ti + 1, k):
                        res = True
                        break

        elif kind == 'DOUBLE_STAR':
            # Matches anything including slashes.
            # Effectively matches the rest of the string, but we must allow subsequent tokens to match.
            # Since ** matches everything, if this is the last token, it matches everything remaining.
            # If there are more tokens, we need to be careful.
            # However, usually ** is greedy. But standard glob behavior:
            # a/**/b matches a/b (so ** matches empty)
            # a/**/b matches a/x/b (so ** matches x/)
            # a/**/b matches a/x/y/b (so ** matches x/y/)

            # Try matching 0 chars, 1 char, ... up to end
            res = False
            # Optimization: If next token is literal or specific, we could search, but generic ** is tricky.
            # Since ** matches ANYTHING, we can just try every position.
            for k in range(pi, len(path) + 1):
                if match(ti + 1, k):
                    res = True
                    break

        elif kind == 'DOUBLE_STAR_SLASH':
            # Matches zero or more directories.
            # Equivalent to matching (empty) OR (anything ending in /)
            # Effectively: match(ti+1, pi) OR match(ti+1, k) where path[k-1] == '/'

            res = False
            # Option 1: Match zero directories (empty string)
            if match(ti + 1, pi):
                res = True
            else:
                # Option 2: Match directories (must end with /)
                # We look for slashes in the remaining path
                k = pi
                while k < len(path):
                    # Find next slash
                    slash_pos = path.find('/', k)
                    if slash_pos == -1:
                        break
                    # We consumed up to slash_pos + 1
                    next_pos = slash_pos + 1
                    if match(ti + 1, next_pos):
                        res = True
                        break
                    k = next_pos

        elif kind == 'CHAR_CLASS':
            negated, chars, ranges = token[1], token[2], token[3]
            if pi >= len(path):
                res = False
            else:
                c = path[pi]
                if c == '/':
                    res = False
                else:
                    in_class = False
                    if c in chars:
                        in_class = True
                    else:
                        for start, end in ranges:
                            if ord(start) <= ord(c) <= ord(end):
                                in_class = True
                                break

                    if negated:
                        matches_char = not in_class
                    else:
                        matches_char = in_class

                    if matches_char:
                        res = match(ti + 1, pi + 1)
                    else:
                        res = False
        else:
            res = False

        memo[(ti, pi)] = res
        return res

    return match(0, 0)
