        # Get lots for SKU, filter out expired, and sort by expires (asc), then by insertion order (stable)
        lots = self.lots.get(sku, [])
        usable_lots = [lot for lot in lots if today <= lot[0]]

        # Sort by expiry date (ascending). Python's sort is stable, so insertion order is preserved for ties.
        usable_lots.sort(key=lambda x: x[0])

        # Check if we have enough stock before modifying anything
        total_usable = sum(lot[1] for lot in usable_lots)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        # Consume from sorted usable lots
        for lot in usable_lots:
            if remaining_qty == 0:
                break
            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        # Clean up empty lots from the main list (including expired ones)
        self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0 and today <= lot[0]]
        if not self.lots[sku]:
            del self.lots[sku]

        return taken

    def stock(self, sku, today):
        lots = self.lots.get(sku, [])
        # Filter out expired lots and sum the rest
        usable_total = sum(lot[1] for lot in lots if today <= lot[0])

        # Clean up expired/empty lots as a side effect of checking stock
        if lots:
            cleaned_lots = [lot for lot in lots if lot[1] > 0 and today <= lot[0]]
            if len(cleaned_lots) != len(lots):
                self.lots[sku] = cleaned_lots
                if not self.lots[sku]:
                    del self.lots[sku]

        return usable_total
