def running_balance(opening, transactions):
    """Apply transactions in order. Each is a dict {"type": "credit" or "debit", "amount": positive int cents}. Returns (closing_balance, balances_after_each_transaction). Balance may go negative on a debit. Raises ValueError for an unknown type or an amount that is not a positive int, before changing anything. Does not modify the input transactions."""

    # Validate all transactions first before modifying anything
    valid_types = {"credit", "debit"}
    for t in transactions:
        if t["type"] not in valid_types:
            raise ValueError(f"Unknown transaction type: {t['type']}")
        amount = t["amount"]
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError(f"Amount must be a positive integer, got: {amount}")

    balances = []
    bal = opening

    # Create a copy of transactions to avoid modifying the input
    # We need to track balances without adding keys to the original dicts
    for t in transactions:
        if t["type"] == "credit":
            bal += t["amount"]
        else:  # type is "debit" here, guaranteed by validation above
            bal -= t["amount"]
        balances.append(bal)

    return bal, balances
