def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Determine sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    if not s:
        return default

    # Validate format: digits optionally separated by single commas in groups of three
    # Allowed: "123", "1,234", "12,345", "1,234,567"
    # Disallowed: "1,23", "1,,234", ",123", "123,", "1_000", "12.34", etc.
    parts = s.split(',')

    # If there are commas, validate grouping
    if len(parts) > 1:
        # First part (leftmost) can be 1 to 3 digits
        if not (1 <= len(parts[0]) <= 3) or not parts[0].isdigit():
            return default
        # All subsequent parts must be exactly 3 digits
        for part in parts[1:]:
            if len(part) != 3 or not part.isdigit():
                return default
    else:
        # No commas: must be all digits
        if not s.isdigit():
            return default

    # Reconstruct digit-only string
    digits = ''.join(parts)

    # Convert to int with sign
    return sign * int(digits)
