    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Pattern: optional sign, then either a single digit or digits with correct comma grouping
    # Correct grouping: optional initial 1-3 digits, then any number of ,ddd groups
    pattern = r'^[+-]?(\d{1,3}(,\d{3})*|\d+)$'
    if not re.match(pattern, s):
        return default

    # Additional check: ensure no consecutive commas or leading/trailing commas (regex mostly covers this, but be explicit)
    if ',' in s:
        parts = s.lstrip('+-').split(',')
        # First part can be 1-3 digits, rest must be exactly 3 digits
        if not (1 <= len(parts[0]) <= 3):
            return default
        if any(len(p) != 3 for p in parts[1:]):
            return default

    try:
        return int(s.replace(",", ""))
    except ValueError:
        return default
