        self.done = {}

    def transfer(self, src, dst, amount, key=None):
        if key in self.done:
            return self.done[key]

        if amount <= 0:
            raise ValueError("amount")
        if src == dst:
            raise ValueError("src equals dst")

        # Check existence of accounts first to ensure no state change on KeyError
        if src not in self.bal:
            raise KeyError(src)
        if dst not in self.bal:
            raise KeyError(dst)

        fee = max(1, amount // 100)
        total_cost = amount + fee

        if self.bal[src] < total_cost:
            if key is not None:
                self.done[key] = False
            return False

        # Perform the transfer
        self.bal[src] -= total_cost
        self.bal[dst] += amount

        if key is not None:
            self.done[key] = True

        return True
