class Bus:
    def __init__(self):
        self.subs = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []
        entry = [priority, handler]  # mutable marker for identity
        self.subs[topic].append(entry)
        # Sort descending by priority; stable for equal priorities (subscription order)
        self.subs[topic].sort(key=lambda x: -x[0])

        def unsubscribe():
            # Remove only this specific entry if present; harmless if already removed
            if topic in self.subs:
                try:
                    self.subs[topic].remove(entry)
                except ValueError:
                    pass  # already removed

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0
        # Snapshot the current list of entries to avoid seeing mutations during emit
        snapshot = list(self.subs[topic])
        n = 0
        for priority, handler in snapshot:
            # Check if this exact entry is still present (not unsubscribed earlier in this emit)
            if topic in self.subs and [priority, handler] in self.subs[topic]:
                handler(*args)
                n += 1
        return n
