def _normalize(obj: Any) -> Any:
    """
    Recursively validate and normalize the object into a JSON-serializable structure
    that preserves type distinctions (list vs tuple) and sorts dictionary keys.
    """
    # Check bool before int because bool is a subclass of int
    if isinstance(obj, bool):
        return ("__bool__", obj)
    if obj is None:
        return ("__none__", None)
    if isinstance(obj, (int, float)):
        return ("__number__", obj)
    if isinstance(obj, str):
        return ("__str__", obj)

    if isinstance(obj, list):
        return ("__list__", [_normalize(item) for item in obj])

    if isinstance(obj, tuple):
        return ("__tuple__", [_normalize(item) for item in obj])

    if isinstance(obj, dict):
        # Validate keys are strings
        for k in obj.keys():
            if not isinstance(k, str):
                raise TypeError(f"Dictionary keys must be strings, got {type(k).__name__}")
        # Sort keys and normalize values
        sorted_items = sorted(obj.items(), key=lambda x: x[0])
        return ("__dict__", [[k, _normalize(v)] for k, v in sorted_items])

    # If none of the above, it's an unsupported type
    raise TypeError(f"Unsupported type for cache key: {type(obj).__name__}")

def cache_key(*args, **kwargs) -> str:
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""

    # Normalize args and kwargs into a canonical structure
    norm_args = _normalize(args)
    norm_kwargs = _normalize(kwargs)

    # Combine into a single structure
    canonical = ("__call__", norm_args, norm_kwargs)

    # Serialize to JSON string
    return json.dumps(canonical, separators=(',', ':'))
