def group_averages(rows):
    sums = {}
    counts = {}
    first_seen = {}

    for name, value in rows:
        # Normalize the key: strip whitespace and convert to lowercase for grouping
        key = name.strip().lower()

        # Store the first seen spelling (with whitespace stripped) for this group
        if key not in first_seen:
            first_seen[key] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
        if key not in sums:
            sums[key] = 0
            counts[key] = 0

        # Only process if value is not None
        if value is not None:
            sums[key] += value
            counts[key] += 1

    result = []
    for key in sums:
        label = first_seen[key]
        count = counts[key]

        if count == 0:
            average = None
        else:
            average = sums[key] / count

        result.append((label, average))

    # Sort by the original label (case-insensitive as per requirement "sorted by name ignoring case")
    # Since the label is the first seen spelling, we sort using the normalized key or the label lowercased
    return sorted(result, key=lambda x: x[0].lower())
