def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    Rules:
    - Variables must start with `prefix`.
    - The part after the prefix is lowercased and split by double underscores (`__`) to form the path.
    - A single underscore is part of the key name, not a separator.
    - Values are cast to the type of the default value.
    - Bool parsing: accepts 1/true/yes/on (True) or 0/false/no/off (False), case-insensitive.
      Anything else raises ValueError.
    - Int and float are parsed numerically.
    - Other types remain strings.
    - Variables without the prefix or paths not existing in defaults are ignored.
    - The defaults object is never modified.
    """
    import copy

    # Deep copy to ensure nested dicts in defaults are not modified
    cfg = copy.deepcopy(defaults)

    def parse_bool(value: str) -> bool:
        v = value.strip().lower()
        if v in ("1", "true", "yes", "on"):
            return True
        if v in ("0", "false", "no", "off"):
            return False
        raise ValueError(f"Invalid boolean value: {value}")

    def convert_value(raw: str, target):
        if isinstance(target, bool):
            return parse_bool(raw)
        if isinstance(target, int):
            return int(raw)
        if isinstance(target, float):
            return float(raw)
        # For any other type (including str), return as string
        return raw

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and split by double underscore for nesting
        key_part = k[len(prefix):]
        path = key_part.split("__")

        # Convert path segments to lowercase, but respect that single underscores are part of keys
        # The split already handles the separation; we just lowercase each segment.
        path = [p.lower() for p in path]

        # Traverse the config to find the target location
        node = cfg
        try:
            for p in path[:-1]:
                if p not in node:
                    # Path does not exist in defaults; ignore this variable
                    break
                node = node[p]
            else:
                # Check if the final key exists
                final_key = path[-1]
                if final_key in node:
                    node[final_key] = convert_value(raw, node[final_key])
        except (KeyError, TypeError, ValueError):
            # Ignore malformed paths or conversion errors for non-existent/invalid paths
            continue

    return cfg
