import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    raw = s.replace(" ", "")
    if not raw:
        raise ValueError("Empty expression")

    toks = []
    i = 0
    while i < len(raw):
        ch = raw[i]
        if ch.isdigit() or ch == ".":
            j = i
            has_dot = (ch == ".")
            j += 1
            while j < len(raw) and (raw[j].isdigit() or raw[j] == "."):
                if raw[j] == ".":
                    if has_dot:
                        raise ValueError("Invalid number")
                    has_dot = True
                j += 1
            toks.append(raw[i:j])
            i = j
        elif ch in "+-*/^()":
            toks.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch}")

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect(tok):
        t = take()
        if t != tok:
            raise ValueError(f"Expected {tok}, got {t}")
        return t

    def expr():
        # + and - (left to right), lowest precedence
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            if op == "+":
                v = v + r
            else:
                v = v - r
        return v

    def term():
        # * and / (left to right)
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError("Division by zero")
                v = v / r
        return v

    def power():
        # ^ (right-associative), tighter than * /, looser than unary
        # But unary binds tighter than ^ on the left: -2^2 = -(2^2)
        # So we parse unary first, then ^ with right-assoc on the right side only.
        v = unary()
        if peek() == "^":
            take()
            # Right-associative: parse the rest of the power chain recursively
            # The exponent itself may start with unary (e.g., 2^-1)
            e = power()  # right-assoc: allow chaining 2^3^2 = 2^(3^2)
            v = v ** e
        return v

    def unary():
        # unary + and -
        t = peek()
        if t == "+":
            take()
            return unary()
        if t == "-":
            take()
            return -unary()
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError(f"Unexpected operator: {t}")
        # Must be a number
        take()
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid number: {t}")

    result = expr()
    if pos != len(toks):
        raise ValueError("Unexpected trailing content")
    return result
