import re


def evaluate(s):
    # Tokenize: numbers (int/float) and operators/parens.
    # Reject unknown characters or empty/no-token input early.
    raw_tokens = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]|.", s)
    toks = []
    for t in raw_tokens:
        if re.fullmatch(r"\d+\.?\d*|\.\d+|[-+*/^()]", t):
            toks.append(t)
        else:
            raise ValueError(f"Invalid character in expression: {t!r}")

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect(tok):
        t = take()
        if t != tok:
            raise ValueError(f"Expected {tok!r}, got {t!r}")

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            if op == "/":
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
            else:
                v = v * r
        return v

    def power():
        # Right-associative exponentiation; exponent may carry its own sign.
        base = unary()
        if peek() == "^":
            take()
            exp = power()  # right-associative
            return base ** exp
        return base

    def unary():
        t = peek()
        if t in ("+", "-"):
            take()
            return (-unary()) if t == "-" else unary()
        return atom()

    def atom():
        t = peek()
        if t == "(":
            take()
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()
            return v
        if t is None:
            raise ValueError("Missing operand")
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError(f"Unexpected operator: {t!r}")
        take()
        return float(t)

    result = expr()
    if pos != len(toks):
        raise ValueError("Unexpected trailing tokens")
    return result
