class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        usable = []
        for lot in self.lots.get(sku, []):
            if today <= lot[0] and lot[1] > 0:
                usable.append(lot)

        # Sort by expiry (earliest first), then by insertion order (stable sort preserves it)
        usable.sort(key=lambda x: x[0])

        # Check if we have enough usable stock
        total_usable = sum(lot[1] for lot in usable)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining = qty

        for lot in usable:
            if remaining == 0:
                break
            n = min(remaining, lot[1])
            lot[1] -= n
            remaining -= n
            taken.append((lot[0], n))

        # Clean up empty lots from the original list
        if sku in self.lots:
            self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0]

        return taken

    def stock(self, sku, today):
        total = 0
        for lot in self.lots.get(sku, []):
            if today <= lot[0] and lot[1] > 0:
                total += lot[1]
        return total
