def set_path(obj, path, value):
    """
    Returns a new structure where the location named by path holds value.
    obj and everything reachable from it is left untouched (deep copy semantics).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index == len(list) appends.
    - Index > len(list) pads with None up to that index.
    - Wrong type for next step raises TypeError.
    - Empty/malformed path raises ValueError.
    - First step must be a key, obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before parsing
    if path.startswith('.') or path.endswith('.'):
        raise ValueError(f"Malformed path: {path}")
    if '..' in path:
        raise ValueError(f"Malformed path: {path}")

    # Parse path into parts
    parts = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                parts.append(('key', current))
                current = ""
            elif i == 0 or path[i-1] == '.':
                raise ValueError(f"Malformed path: {path}")
        elif ch == '[':
            if current:
                parts.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError(f"Malformed path: {path}")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError(f"Malformed path: {path}")
            if not index_str.isdigit():
                raise ValueError(f"Malformed path: {path}")
            if index_str.startswith('0') and len(index_str) > 1:
                raise ValueError(f"Malformed path: {path}")
            parts.append(('index', int(index_str)))
            i = j
        elif ch == ']':
            raise ValueError(f"Malformed path: {path}")
        else:
            current += ch
        i += 1

    if current:
        parts.append(('key', current))

    if not parts:
        raise ValueError("path must have at least one component")

    if parts[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy the object to ensure immutability of original
    result = copy.deepcopy(obj)

    # Navigate and build the structure
    node = result

    for i, (step_type, step_val) in enumerate(parts[:-1]):
        next_type, next_val = parts[i + 1]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at path step, got {type(node).__name__}")

            if step_val not in node:
                # Create new container based on next step
                if next_type == 'key':
                    node[step_val] = {}
                else:
                    node[step_val] = []

            node = node[step_val]

        else:  # step_type == 'index'
            if not isinstance(node, list):
                raise TypeError(f"Expected list at path step, got {type(node).__name__}")

            if step_val < 0:
                raise ValueError(f"Negative index not allowed: {step_val}")

            # Pad list if necessary
            while len(node) <= step_val:
                node.append(None)

            if node[step_val] is None:
                # Create new container based on next step
                if next_type == 'key':
                    node[step_val] = {}
                else:
                    node[step_val] = []
            elif next_type == 'key' and not isinstance(node[step_val], dict):
                raise TypeError(f"Expected dict at path step, got {type(node[step_val]).__name__}")
            elif next_type == 'index' and not isinstance(node[step_val], list):
                raise TypeError(f"Expected list at path step, got {type(node[step_val]).__name__}")

            node = node[step_val]

    # Set the final value
    last_type, last_val = parts[-1]

    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at final step, got {type(node).__name__}")
        node[last_val] = value
    else:  # last_type == 'index'
        if not isinstance(node, list):
            raise TypeError(f"Expected list at final step, got {type(node).__name__}")

        if last_val < 0:
            raise ValueError(f"Negative index not allowed: {last_val}")

        # Pad list if necessary
        while len(node) < last_val:
            node.append(None)

        if last_val == len(node):
            node.append(value)
        else:
            node[last_val] = value

    return result
