def set_path(obj, path, value):
    if not path or path.startswith(".") or path.endswith("."):
        raise ValueError("Malformed path")
    if ".." in path:
        raise ValueError("Malformed path")
    if "[" in path:
        # Check for malformed brackets
        depth = 0
        for i, ch in enumerate(path):
            if ch == '[':
                depth += 1
                # Check if next char is not a digit or minus (though minus is invalid per spec too)
                if i + 1 < len(path) and not path[i+1].isdigit():
                    raise ValueError("Malformed path")
            elif ch == ']':
                depth -= 1
                if depth < 0:
                    raise ValueError("Malformed path")
        if depth != 0:
            raise ValueError("Malformed path")

        # Check for negative indices or non-numeric indices inside brackets
        import re
        brackets = re.findall(r'\[(.*?)\]', path)
        for b in brackets:
            if not b.isdigit():
                raise ValueError("Malformed path")
            if b.startswith('-') or (b and b[0] == '-'): # redundant check but safe
                raise ValueError("Malformed path")

    if not isinstance(obj, dict):
        raise TypeError("First step must be a key and obj must be a dict")

    # Deep copy helper to ensure immutability of original obj
    def deep_copy(o):
        if isinstance(o, dict):
