def deep_merge(base, override):
    """Return a new dict with the keys of both. When both values for a key are dicts they are merged recursively; otherwise the override value wins (even None). Neither input is modified, and the result shares no mutable dict or list with either input."""
    # Create a shallow copy of base to ensure we don't modify the original
    result = dict(base)

    for k, v in override.items():
        if isinstance(v, dict) and isinstance(result.get(k), dict):
            # Recursively merge nested dicts
            result[k] = deep_merge(result[k], v)
        else:
            # For non-dict values (including None) or when base doesn't have the key as a dict,
            # we need to ensure we don't share mutable objects like lists
            if isinstance(v, list):
                result[k] = list(v)
            elif isinstance(v, dict):
                # This case happens when override has a dict but base doesn't, or base has non-dict
                result[k] = dict(v)
            else:
                result[k] = v

    return result
```

