The bug is in the `add()` function. It uses right-recursion (`v - add()`) instead of left-associative iteration, causing `10-4-3` to parse as `10-(4-3) = 9` instead of `(10-4)-3 = 3`. Additionally, the code lacks validation for malformed input (junk tokens, unbalanced parentheses, consecutive numbers, dangling operators), which the docstring explicitly forbids.

Here is the corrected module:

```python
import re


def evaluate(expr):
    """Evaluate an arithmetic expression with integers, + - * /, parentheses, unary minus and spaces. Standard precedence (* and / before + and -), all binary operators left associative. '/' is true division (a float). Malformed input (empty, unbalanced parentheses, dangling operator, two numbers in a row, any other character) raises ValueError. Division by zero raises ZeroDivisionError."""
    # Validate characters first: only digits, operators, parens, and whitespace allowed
    if re.search(r"[^\d+\-*/()\s]", expr):
        raise ValueError("Invalid character in expression")

    tokens = re.findall(r"\d+|[-+*/()]", expr)

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = eat()
        if t == "(":
            v = add()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            eat()  # consume ')'
            return v
        if t == "-":
            # Unary minus: must be followed by a valid atom (number, '(', or another '-')
            return -atom()
        if t in ("+", "*", "/", ")"):
            raise ValueError(f"Unexpected operator or parenthesis: {t}")
        # Must be a number
        try:
            return int(t)
        except ValueError:
            raise ValueError(f"Invalid token: {t}")

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            right = atom()
            if op == "*":
                v = v * right
            else:
                v = v / right
        return v

    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = eat()
            right = mul()  # Left-associative: parse next mul() term, not recursive add()
            if op == "+":
                v = v + right
            else:
                v = v - right
        return v

    result = add()

    # Ensure all tokens were consumed (no trailing junk)
    if pos < len(tokens):
        raise ValueError("Extra tokens after expression")

    return result
