import json


def _normalize(obj):
    """Recursively normalize data structures for stable serialization.

    - Lists are converted to tuples.
    - Dicts are sorted by key and converted to tuples of (key, value) pairs.
    - This ensures that [1, 2] != (1, 2) after normalization because their 
      outer type tag will differ, but {"b": 2, "a": 1} == {"a": 1, "b": 2}.
    """
    if isinstance(obj, bool):
        # Must check bool before int because bool is a subclass of int
        return ('__bool__', obj)
    if isinstance(obj, (int, float)):
        # Distinguish between int and float (e.g., 1 vs 1.0)
        return (type(obj).__name__, obj)
    if isinstance(obj, str):
        return ('__str__', obj)
    if obj is None:
        return ('__none__', None)
    if isinstance(obj, list):
        return ('__list__', tuple(_normalize(item) for item in obj))
    if isinstance(obj, tuple):
        return ('__tuple__', tuple(_normalize(item) for item in obj))
    if isinstance(obj, dict):
        # Validate keys are strings and sort them
        items = []
        for k, v in obj.items():
            if not isinstance(k, str):
                raise TypeError("Dict keys must be strings")
            items.append((k, _normalize(v)))
        items.sort(key=lambda x: x[0])
        return ('__dict__', tuple(items))

    raise TypeError(f"Unsupported type: {type(obj)}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""

    # Normalize args and kwargs to ensure stable ordering and type distinction
    normalized_args = tuple(_normalize(arg) for arg in args)

    # Sort kwargs by key to ensure order independence
    sorted_kwargs_keys = sorted(kwargs.keys())
    normalized_kwargs = tuple((k, _normalize(kwargs[k])) for k in sorted_kwargs_keys)

    # Create a structure that distinguishes between positional and keyword arguments
    # and preserves type information through the normalization tags
    payload = {
        'args': normalized_args,
        'kwargs': normalized_kwargs
    }

    return json.dumps(payload, sort_keys=True)
