```python
def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    # Strip surrounding whitespace
    s = text.strip()

    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    # After removing sign, must not be empty
    if not s:
        return default

    # Split by comma to validate grouping
    parts = s.split(',')

    # If there are commas, validate grouping:
    # - All parts must be non-empty
    # - All parts must consist only of ASCII digits
    # - All parts except the first must be exactly 3 digits
    # - The first part must be 1 to 3 digits (and not start with 0 unless it's just "0")
    if len(parts) > 1:
        for i, part in enumerate(parts):
            if not part:
                return default
            if not part.isdigit():
                return default
            if not all(c in '0123456789' for c in part):  # Ensure ASCII digits only
                return default
            if i == 0:
                # First part: 1 to 3 digits, no leading zero unless it's exactly "0"
                if len(part) > 3:
                    return default
                if len(part) > 1 and part[0] == '0':
                    return default
            else:
                # Subsequent parts must be exactly 3 digits
                if len(part) != 3:
                    return default
    else:
        # No commas: just validate it's ASCII digits, no leading zero unless "0"
        part = parts[0]
        if not part:
            return default
        if not part.isdigit():
            return default
        if not all(c in '0123456789' for c in part):  # Ensure ASCII digits only
            return default
        if len(part) > 1 and part[0] == '0':
            return default

    # Reconstruct the digit string without commas
    digit_str = ''.join(parts)

    # Convert to int and apply sign
    try:
        value = int(digit_str)
        return sign * value
    except ValueError:
        return default
```

The bug is in the `cache_key` function. It uses `json.dumps([args, kwargs])` directly, which has two problems:

1. **Keyword argument order**: While Python 3.7+ dicts maintain insertion order, `json.dumps` will serialize kwargs in the order they appear in the dict. If `cache_key(a=1, b=2)` is called vs `cache_key(b=2, a=1)`, the kwargs dict will have different internal ordering, producing different JSON strings.

2. **List vs tuple collision**: `json.dumps` converts both lists and tuples to JSON arrays, so `[1, 2]` and `(1, 2)` both become `[1, 2]` in JSON, causing a collision.

The fix requires:
1. Sort kwargs by key before serializing to ensure consistent ordering
2. Include type information to distinguish lists from tuples (and other types that JSON conflates)

Here's the corrected module:

```python
import json


def _normalize_for_cache_key(obj):
    """Normalize a value for cache key generation, preserving type information."""
    if obj is None:
        return ['__none__', None]
    elif isinstance(obj, bool):
        # Must check bool before int since bool is subclass of int
        return ['__bool__', obj]
    elif isinstance(obj, int):
        return ['__int__', obj]
    elif isinstance(obj, float):
        return ['__float__', obj]
    elif isinstance(obj, str):
        return ['__str__', obj]
    elif isinstance(obj, list):
        return ['__list__', [_normalize_for_cache_key(item) for item in obj]]
    elif isinstance(obj, tuple):
        return ['__tuple__', [_normalize_for_cache_key(item) for item in obj]]
    elif isinstance(obj, dict):
        # Validate all keys are strings
        for key in obj.keys():
            if not isinstance(key, str):
                raise TypeError(f"Dict keys must be strings, got {type(key).__name__}")
        # Sort by key for consistent ordering
        sorted_items = sorted(obj.items(), key=lambda x: x[0])
        return ['__dict__', [_normalize_for_cache_key(k), _normalize_for_cache_key(v)] for k, v in sorted_items]
    else:
        raise TypeError(f"Unsupported type for cache_key: {type(obj).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    normalized_args = [_normalize_for_cache_key(arg) for arg in args]
    # Sort kwargs by key for consistent ordering regardless of call order
    sorted_kwargs = sorted(kwargs.items(), key=lambda x: x[0])
    normalized_kwargs = [[k, _normalize_for_cache_key(v)] for k, v in sorted_kwargs]
    return json.dumps([normalized_args, normalized_kwargs], sort_keys=True)
